# c375: 테이저 번개는 떠 있는 드론까지 · 드론 출동 = 난리남 1분 뒤, 30초마다 단계별 1·1·2·2 · 좌우 선회 · 히드라는 드론 1순위
C375_R = [('const [bx, by] = zp.to ? toScreen(zp.to.foot.x, zp.to.foot.z, W, H) : [ax + 18, ay - 18];', 'const [bx, by] = zp.to ? (zp.to.drone ? (sV.copy(zp.to.s.position).project(camera), [(sV.x + 1) / 2 * W, (1 - sV.y) / 2 * H + 14]) : toScreen(zp.to.foot.x, zp.to.foot.z, W, H)) : [ax + 18, ay - 18];   /* c375: 드론은 떠 있는 그림까지 번개가 올라간다 */'), ('if (!chDroneOn && stars >= 2 && isZombie(me)) { chDroneOn = true; chDroneT = CH_DRONE_EVERY; }   // 난리남이 되는 순간 첫 출동', 'if (!chDroneOn && stars >= 2 && isZombie(me)) { chDroneOn = true; chDroneT = CH_DRONE_EVERY - 60; }   // c375: 난리남이 되고 1분 뒤 첫 출동 (표시 없이)'), ('for (let i = 0; i < CH_DRONE_N && chDrones.length < CH_DRONE_MAX; i++) {', 'for (let i = 0, N = Math.max(1, Math.ceil((stars - 1) / 2)); i < N && chDrones.length < CH_DRONE_MAX; i++) {   /* c375: 난리남 1 · 개판 1 · 계엄 2 · 데프콘 2 (두 단계마다 한 대씩) */'), ('window.__drones = () => chDrones;', 'window.__droneT = () => [chDroneOn, +chDroneT.toFixed(1)]; window.__drones = () => chDrones;'), ('const air = d.air, y = Math.max(0.35, air + (air > 0.5 ? Math.sin(d.bob) * 0.12 : 0));', 'const air = d.air, y = Math.max(0.35, air);   /* c375: 위아래로는 안 흔들린다 (좌우 선회는 진짜 자리에서) */'), ('      d.foot.set(d.x, 0, d.z);\n', '      if (d.stunT <= 0) {                       // c375: 벌처럼 둥둥 — 바닥 평면에서 좌우로 작은 8자 선회 (진짜 자리 = 그림자도 같이)\n        const wx = Math.sin(d.bob * 1.1) * 0.32, wz = Math.sin(d.bob * 2.2) * 0.16, ox = d.wx || 0, oz = d.wz || 0;\n        if (chDroneFree(d.x + wx - ox, d.z + wz - oz)) { d.x += wx - ox; d.z += wz - oz; d.wx = wx; d.wz = wz; }\n      }\n      d.foot.set(d.x, 0, d.z);\n'), ("    if (CHAPTER && z.mut === 'hydra' && !z.space) for (const dr of chDrones) { const q = Math.hypot(dr.x - z.foot.x, dr.z - z.foot.z); if (!dr.dead && q < bd && q <= zs && !fireBlocked(z.foot.x, z.foot.z, dr.x, dr.z)) { bd = q; t = dr; } }", "    if (CHAPTER && z.mut === 'hydra' && !z.space) { let dq = Infinity, dt2 = null; for (const dr of chDrones) { const q = Math.hypot(dr.x - z.foot.x, dr.z - z.foot.z); if (!dr.dead && q < dq && q <= zs && !fireBlocked(z.foot.x, z.foot.z, dr.x, dr.z)) { dq = q; dt2 = dr; } } if (dt2) { bd = dq; t = dt2; } }   // c375: 히드라는 드론이 1순위 (보이는 드론 중 가장 가까운 것)"), ("go = t || prey || adj || (CHAPTER && z === me && z.mut === 'hydra' && !z.space ? chHydDrone(z) : null);", "go = (CHAPTER && z === me && z.mut === 'hydra' && !z.space ? chHydDrone(z) : null) || t || prey || adj;   /* c375: 히드라인 나도 드론이 1순위 */")]
